<template>
  <div>
    <sg-nav></sg-nav>
    <main class="container account-page">
      <section class="account-shell tcommonBox">
        <aside class="account-aside"><div class="aside-mark">ACCOUNT / LAB</div><img :src="userInfoObj.avatar || defaultAvatar" :onerror="$store.state.errorImg" alt="头像"><h1>{{ userInfoObj.nickName || 'YanBlog 用户' }}</h1><p>管理你在社区中的公开资料</p><a href="javascript:void(0);" @click="goProfile"><i class="fa fa-user-o"></i> 查看我的主页</a><a href="#/WriteArticle"><i class="fa fa-pencil"></i> 写一篇文章</a></aside>
        <section class="account-content"><header><p>PERSONAL SETTINGS</p><h2>个人中心</h2><span>只会更新头像、昵称和性别；邮箱不会在公开主页展示。</span></header><el-form ref="form" :model="userInfoObj" label-position="top" class="account-form"><el-form-item label="头像"><el-upload class="avatar-upload" name="img" :action="uploadURL" :show-file-list="false" :on-success="handleAvatarSuccess" :before-upload="beforeAvatarUpload"><img v-if="userInfoObj.avatar" :src="userInfoObj.avatar" :onerror="$store.state.errorImg" alt=""><i v-else class="el-icon-plus"></i><span class="avatar-copy">更换头像</span></el-upload></el-form-item><el-form-item label="昵称"><el-input v-model.trim="userInfoObj.nickName" maxlength="32" show-word-limit placeholder="展示给其他用户的名称" /></el-form-item><el-form-item label="邮箱"><el-input :value="userInfoObj.email" disabled /></el-form-item><el-form-item label="性别"><el-radio-group v-model="userInfoObj.sex"><el-radio label="0">男</el-radio><el-radio label="1">女</el-radio><el-radio label="2">保密</el-radio></el-radio-group></el-form-item><div class="account-actions"><el-button @click="goProfile">取消</el-button><el-button type="primary" :loading="saving" @click="saveInfoFun">保存资料</el-button></div></el-form></section>
      </section>
    </main>
  </div>
</template>

<script>
import header from '../components/header.vue'
import { getUserInfo, savaUserInfo } from '../api/user.js'
import store from '../store'
export default { name: 'UserInfo', components: { 'sg-nav': header }, data() { return { uploadURL: '', userInfoObj: {}, saving: false, defaultAvatar: 'static/img/tou.jpg' } }, created() { this.uploadURL = store.state.baseURL + 'upload'; this.loadUser() }, methods: { loadUser() { const user = JSON.parse(localStorage.getItem('userInfo') || 'null'); if (!user) return; getUserInfo(user.id).then(data => { this.userInfoObj = data || {} }) }, handleAvatarSuccess(res) { if (res.code === 200) this.userInfoObj.avatar = res.data; else this.$message.error('上传图片失败') }, beforeAvatarUpload(file) { const valid = ['image/png', 'image/jpg', 'image/jpeg'].includes(file.type) && file.size / 1024 / 1024 < 1; if (!valid) this.$message.error('请上传 1MB 以内的 JPG/JPEG/PNG 图片'); return valid }, saveInfoFun() { if (!this.userInfoObj.nickName) { this.$message.error('昵称不能为空'); return } this.saving = true; savaUserInfo(this.userInfoObj).then(() => { const current = JSON.parse(localStorage.getItem('userInfo') || '{}'); current.nickName = this.userInfoObj.nickName; current.avatar = this.userInfoObj.avatar; localStorage.setItem('userInfo', JSON.stringify(current)); this.$message.success('资料已保存') }).finally(() => { this.saving = false }) }, goProfile() { const user = JSON.parse(localStorage.getItem('userInfo') || 'null'); if (user) this.$router.push({ path: '/UserProfile', query: { userId: user.id } }) } } }
</script>

