py{opacity:1}.account-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:28px;padding-top:20px;border-top:1px solid #edf0f4}.account-actions .el-button--primary{border-color:#5e5997;background:#5e5997}@media screen and (max-width:700px){.account-shell{grid-template-columns:1fr}.account-aside{padding:27px 22px}.aside-mark{margin-bottom:14px}.account-aside img{width:76px;height:76px}.account-aside p{margin-bottom:12px}.account-aside a{display:none}.account-content{padding:28px 22px}.account-content h2{font-size:24px}}
